    'admin.push.how_text' => 'Push — это короткие сообщения, которые браузер показывает, даже когда вкладка закрыта. Администраторы получают их о новых заказах и срабатывании правил автоматизации, а клиенты — только рассылку отсюда, если согласились на уведомления на сайте. Ничего не нужно подключать: ключи создаются автоматически, сторонние сервисы не используются. Нужны https-адрес сайта, включённый переключатель ниже и хотя бы одно устройство, где вы нажали «Включить на этом устройстве».',
