    'admin.guide.stripe.what' => 'Онлайн-оплата картой, Apple Pay и Google Pay на странице Stripe в более чем 135 валютах.',
    'admin.guide.stripe.how' => 'В кабинете Stripe откройте Developers → API keys и скопируйте Secret key (sk_live_… или sk_test_…). Добавьте webhook на адрес https://ваш-домен/webhooks/payments/stripe с событиями checkout.session.completed, checkout.session.expired, checkout.session.async_payment_succeeded, checkout.session.async_payment_failed и скопируйте Signing secret в STRIPE_WEBHOOK_SECRET. Для проверки сначала пользуйтесь тестовыми ключами.',
    'admin.guide.google_pay.what' => 'Кнопка Google Pay на странице оплаты: покупатель платит картой, сохранённой в аккаунте Google.',
    'admin.guide.google_pay.how' => 'Сначала подключите Stripe. Скопируйте Publishable key в Stripe → Developers → API keys. Во время тестирования оставьте GOOGLE_PAY_ENVIRONMENT=TEST. Для PRODUCTION зарегистрируйте сайт в Google Pay & Wallet Console, получите merchant ID и дождитесь одобрения интеграции Google (понадобятся скриншоты страницы оплаты). В webhook Stripe включите payment_intent.succeeded и payment_intent.payment_failed.',
    'admin.guide.paypal.what' => 'Оплата через PayPal или карту PayPal: USD, EUR, GBP, PLN, CZK и другие.',
    'admin.guide.paypal.how' => 'На developer.paypal.com создайте приложение (REST app) и скопируйте Client ID и Secret. Сначала укажите PAYPAL_SANDBOX=1 с ключами песочницы. Для подтверждения оплат без возврата покупателя добавьте webhook https://ваш-домен/webhooks/payments/paypal с событием PAYMENT.CAPTURE.COMPLETED и скопируйте его Webhook ID в PAYPAL_WEBHOOK_ID.',
    'admin.checkout_methods.note.dhl' => 'Пункты выдачи и постаматы DHL; нужен ключ DHL_API_KEY.',
    'admin.checkout_methods.note.gls' => 'Пункты GLS ParcelShop; нужны настройки GLS в .env.',
    'admin.guide.dhl.what' => 'Доставка DHL: поиск пунктов выдачи и постаматов в городе покупателя (страны Европы).',
    'admin.guide.dhl.how' => 'На developer.dhl.com зарегистрируйтесь, создайте приложение с API Location Finder и скопируйте API key в DHL_API_KEY. После этого включите DHL в разделе «Способы доставки и оплаты».',
    'admin.guide.gls.what' => 'Доставка GLS: пункты ParcelShop в городе покупателя.',
    'admin.guide.gls.how' => 'Адрес API, токен и путь к списку пунктов предоставляет ваш офис GLS по договору. Впишите их в GLS_API_BASE, GLS_API_TOKEN, GLS_POINTS_PATH и включите GLS в «Способы доставки и оплаты». Если ответ имеет другой формат, покупатель всегда может указать адрес вручную.',
