    'admin.conn.hint_mono_parts' => '«Покупка частинами» от monobank. Покупатель подтверждает в приложении monobank. Идентификатор магазина и секрет предоставляет monobank; перечень частей — то, что банк разрешил вашему магазину (например 3,4,6,10). Автоподтверждение сразу подтверждает заказ банку, когда покупатель согласился; выключите его, если подтверждаете после передачи товара.',
    'admin.conn.hint_privat_parts' => '«Оплата частями» от ПриватБанка (PayParts v2). Идентификатор магазина и пароль — в кабинете мерчанта ПриватБанка. PP — «оплата частями», II — «мгновенная рассрочка». Части — количество платежей, которое видит покупатель (от 2 до 24 по договору).',
    'admin.conn.hint_liqpay' => 'LiqPay (карты, Приват24, Apple Pay, Google Pay). Публичный и приватный ключи: кабинет LiqPay → Компания → API.',
