    'admin.conn.hint_stripe' => 'Stripe (карты и локальные методы вашего аккаунта). Секретный ключ и webhook secret: Stripe dashboard → Developers. STRIPE_PAYMENT_METHODS (необязательно) — какие методы предлагать, например card,ideal,blik,klarna,sepa_debit; пусто — Stripe выберет по настройкам вашего кабинета. Каждый метод должен быть включён и в кабинете Stripe и подходить к валюте заказа (iDEAL, SEPA, Klarna: EUR; BLIK: PLN).',
    'admin.conn.hint_google_pay' => 'Кнопка Google Pay на отдельной странице оплаты. Нужен подключённый выше Stripe (карта списывается через Stripe). Publishable key: кабинет Stripe → Developers → API keys (pk_live_… или pk_test_…). Среда TEST работает без одобрения Google; для PRODUCTION укажите merchant ID из Google Pay & Wallet Console. В вебхуке Stripe дополнительно включите события payment_intent.succeeded и payment_intent.payment_failed.',
