    'admin.help.sf.logo_height.ex' => '56 для узкого горизонтального логотипа, 80 для почти квадратного',
    'admin.help.sf.icon' => 'Знак без надписи для мест, где полный логотип не помещается. Загрузите его в медиатеку и выберите здесь.',
    'admin.help.sf.icon.ex' => 'квадратный PNG 512×512 px',
    'admin.help.sf.favicon' => 'Маленький значок во вкладке браузера рядом с названием страницы.',
    'admin.help.sf.favicon.ex' => 'квадратный PNG 512×512 px',
    'admin.help.sf.show_title' => 'Отключайте, когда название уже есть на самом логотипе: тогда рядом с ним текст не выводится. Название для поисковых систем и alt-текста не меняется.',
    'admin.help.sf.show_title.ex' => 'на логотипе уже написано «Гараж-Моторс»',
    'admin.help.pl.bulk' => 'Действует на товары, отмеченные в таблице. «Опубликовать», «В черновики» и «Архивировать» меняют статус; «Копировать» создаёт черновики (до 50 за раз); обнуление остатка можно отменить. Действия «ИИ» открывают страницу пакетной работы ИИ: готовые тексты сначала идут на проверку, товары не меняются.',
    'admin.help.pl.columns' => 'Отмеченные колонки показываются в таблице. Кнопка «Сохранить вид» запоминает их вместе с поиском.',
    'admin.help.pl.quick' => 'Цену и остаток можно изменить прямо в таблице: Enter или выход из поля сохраняет, Esc возвращает старое значение. Цена — до двух знаков после точки, остаток — до шести. Остаток редактируется только у товаров с одним вариантом; у товаров с вариантами показана сумма, меняйте её в карточке товара.',
    'admin.help.pl.quick.ex' => '249.90 в цене, 7.5 в остатке',
    'admin.help.pl.status' => 'Переключатель в колонке «Статус» публикует товар или возвращает его в черновик без открытия карточки. У архивных товаров переключателя нет.',
    'admin.help.cl.count' => 'Число — все товары категории вместе со всеми подкатегориями, клик открывает их список. Количество товаров самой категории видно в подсказке при наведении.',
    'admin.help.cl.sort' => 'Меньшее число — выше среди категорий одного уровня. Порядок можно изменить в таблице или перетаскиванием строк.',
    'admin.help.cl.sort.ex' => '10, 20, 30 — тогда новую категорию можно вставить как 15',
    'admin.help.cf.slug' => 'Часть адреса страницы категории латиницей. Пустое поле — адрес создаётся из названия.',
    'admin.help.cf.slug.ex' => 'fuel-pumps',
    'admin.help.cf.sort' => 'Меньшее число — выше среди категорий одного уровня; 0 по умолчанию.',
    'admin.help.cf.sort.ex' => '10',
    'admin.help.cf.h1' => 'Заголовок на странице категории, когда он должен отличаться от названия в меню.',
    'admin.help.cf.h1.ex' => 'название «Насосы», H1 «Топливные насосы для дизеля»',
    'admin.help.cf.title' => 'Строка, которую Google показывает как заголовок категории в выдаче. Начинайте с главного запроса.',
    'admin.help.cf.title.ex' => 'Топливные насосы для дизеля — купить в Киеве',
    'admin.help.cf.description' => 'Текст под заголовком в выдаче Google: что посетитель найдёт в категории. Кнопка ИИ под формой готовит его по названию.',
    'admin.help.pf.sku' => 'Ваш внутренний код товара. Его находит строка «Название или SKU» в списке товаров, он же является ключом при импорте из файла.',
    'admin.help.pf.sku.ex' => 'GTR-001',
    'admin.help.pf.status' => 'Черновик и Архив не показываются покупателям; Опубликовано — товар доступен на витрине.',
    'admin.help.pf.price' => 'Цена для покупателя в валюте, код которой стоит рядом с названием поля. Копейки через точку или запятую, до двух знаков.',
    'admin.help.pf.price.ex' => '249.90',
    'admin.help.pf.stock' => 'Количество на складе рынка; до шести знаков после точки для товаров на вес или метраж. Для цифровых товаров поле отключено.',
    'admin.help.pf.stock.ex' => '12 или 7.5',
