    'admin.help.pf.title' => 'Строка, которую Google показывает как заголовок товара в выдаче. Пустое поле — берётся название товара.',
    'admin.help.pf.title.ex' => 'Топливный насос GTR-200 — цена, наличие',
    'admin.help.pf.description' => 'Текст под заголовком в выдаче Google. Пустое поле — берётся краткое описание. Кнопка ИИ под формой готовит его по названию и описанию.',
    'admin.help.pf.ai' => 'Кнопка вставляет черновик краткого и полного описания в форму; в товар он попадёт только после «Сохранить товар». Каждое обращение к модели учитывается в дневном лимите на странице «ИИ-помощник».',
    'admin.help.tr.provider' => 'Модель, которая переводит. Ключи и выбор модели — в разделе «Система → ИИ-помощник». Термины из словаря не переводятся или заменяются вашим вариантом.',
    'admin.help.tr.all' => 'Перевод всех полей на все языки магазина за один проход; результат лишь подставляется в формы, сохранение — кнопкой «Сохранить все языки».',
    'admin.help.ai.limit' => 'Сколько обращений к модели разрешено в сутки; каждый запрос, в том числе часть длинного текста, учитывается отдельно. Счётчик сбрасывается в 00:00 UTC. По умолчанию 200.',
    'admin.help.ai.limit.ex' => '500',
    'admin.help.ai.glossary_term' => 'Слово или название так, как они стоят в тексте. Совпадение целым словом, без учёта регистра; теги HTML не затрагиваются.',
    'admin.help.ai.glossary_term.ex' => 'Nexora, GTR-200',
    'admin.help.ab.mode' => '«Только непереведённое» не трогает готовые переводы и поэтому тратит меньше запросов; «Перевести всё заново» перезаписывает имеющиеся тексты.',
    'admin.help.ab.types' => 'Что переводить. Товары дают больше всего запросов: каждое поле товара на каждый язык.',
    'admin.help.ab.run' => 'Фоновая очередь сама обрабатывается по расписанию (Система → Cron / Автоматизация). Кнопка выполняет один раунд сейчас, пока страница открыта.',
    'admin.help.ab.review' => 'Тексты от ИИ лежат здесь, пока вы не примените их к товарам. Применение можно отменить.',
